function shellPixels(){let r=Math.random();return r<.35?'office':r<.7?'interview':'class'}
function home(){app.innerHTML=`<section class="hero"><div><div class="eyebrow">AI CAREER LIFE SIMULATOR · SEASON 01</div><h1>ฝึกงานครั้งนี้<br>จะพาคุณไป<em>ไกลแค่ไหน?</em></h1><p>จำลองเส้นทางสหกิจศึกษา 10 เดือน ตั้งแต่ส่งใบสมัครจนถึงวันสุดท้ายในบริษัท ตัดสินใจ ฝึกทักษะ พลาดได้ เรียนรู้ได้ แล้วเขียนตอนจบในแบบของคุณ</p><div class="stats"><div><b>584</b><span>ตำแหน่งจากข้อมูลจริง</span></div><div><b>${TOTAL_EVENT_POOL.toLocaleString()}+</b><span>เหตุการณ์ในคลัง</span></div><div><b>${SCENARIO_THEMES}</b><span>ธีมสถานการณ์ · เจอ 60–100 ต่อรอบ</span></div><div><b>2,500+</b><span>ฉากจบพร้อมเรื่องราว/ภาพ</span></div></div><button class="primary" onclick="go('profile')">เริ่มต้นชีวิตฝึกงาน <span>→</span></button><p class="fine">ใช้เวลาประมาณ 1–2 ชั่วโมง · ทุกตัวละครเป็น AI จำลอง · โปรไฟล์เก็บในอุปกรณ์นี้</p><p class="notice">${SIM_NOTICE}</p></div><div class="pixel-card"><canvas id="heroart"></canvas><div class="caption"><span>PROCEDURAL PIXEL WORLD</span><span>10,000+ SCENE VARIATIONS</span></div></div></section>`;pixel($('#heroart'),'office',Math.random()*99999)}
function go(s){state.screen=s;render()}
function profile(){app.innerHTML=`<section class="panel"><div class="stephead"><span class="stepno">01 / 05</span><h2>ยื่น CV ให้พี่ WIL ก่อนเริ่มจับคู่</h2><small>UPLOAD CV · MATCH YOUR FUTURE ROLE</small></div><p class="muted">เริ่มจากอัปโหลด CV PDF เพื่อให้ระบบอ่านข้อความและจับคู่ตำแหน่งฝึกงานจากฐานข้อมูลย้อนหลัง 5 ปี ไฟล์ถูกอ่านในเบราว์เซอร์และไม่ส่งขึ้นเซิร์ฟเวอร์</p><form id="profileForm"><div class="formgrid"><div class="field full"><label>CV ของคุณ (PDF) <span class="muted">— จำเป็นสำหรับเริ่มเกม</span></label><label class="upload">▧ <span id="filename">คลิกเพื่อเลือก CV PDF</span><input id="cv" type="file" accept=".pdf,application/pdf" required></label><div id="cvStatus" class="small">ระบบจะอ่านข้อความจาก PDF บนอุปกรณ์นี้</div></div><div class="field"><label>ชื่อเล่น</label><input name="name" placeholder="เช่น มะลิ" required></div><div class="field"><label>สาขาวิชา</label><input name="major" placeholder="เช่น เทคโนโลยีสารสนเทศ" required></div><div class="field"><label>อยากลองสายงานไหน</label><select name="interest"><option value="dev">พัฒนาโปรแกรม / IT</option><option value="design">ออกแบบ / UX UI / สื่อ</option><option value="marketing">การตลาดดิจิทัล</option><option value="analyst">วิเคราะห์ข้อมูล / ธุรกิจ</option><option value="test">ทดสอบซอฟต์แวร์ / QA</option><option value="support">ประสานงาน / บริการ</option><option value="general">ยังไม่แน่ใจ</option></select></div><div class="field"><label>ทักษะที่มี (คั่นด้วยจุลภาค)</label><input name="skills" placeholder="เช่น HTML, Figma, Excel, สื่อสาร" required></div><div class="field full"><label>เล่าโปรเจกต์หรือสิ่งที่ภูมิใจ</label><textarea name="about" placeholder="งานกลุ่ม โปรเจกต์เรียน งานอดิเรก หรือสิ่งที่อยากเรียนรู้"></textarea></div></div><div class="rowactions"><span class="small">🔒 CV อยู่ในอุปกรณ์นี้ · ทักษะจาก PDF และข้อมูลที่กรอกจะช่วยจัดอันดับตำแหน่ง</span><button class="primary">จับคู่ตำแหน่งจาก CV →</button></div></form></section>`;$('#cv').onchange=e=>{let file=e.target.files[0];$('#filename').textContent=file?.name||'คลิกเพื่อเลือก CV PDF';$('#cvStatus').textContent=file?'เลือกไฟล์แล้ว · ระบบจะอ่าน CV ก่อนจับคู่':'ระบบจะอ่านข้อความจาก PDF บนอุปกรณ์นี้'};$('#profileForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target);state.profile=Object.fromEntries(f);let file=$('#cv').files[0];if(!file)return;state.cv=file.name;state.profile.cvText='';state.profile.cvReadStatus='';if(window.pdfjsLib){$('#cvStatus').textContent='กำลังอ่านข้อความจาก CV PDF บนอุปกรณ์นี้…';try{pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';let doc=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;let pages=[];for(let n=1;n<=Math.min(doc.numPages,8);n++){let page=await doc.getPage(n);let content=await page.getTextContent();pages.push(content.items.map(x=>x.str).join(' '))}state.profile.cvText=pages.join(' ').slice(0,24000);state.profile.cvReadStatus=state.profile.cvText?'อ่าน CV PDF แล้ว · '+state.profile.cvText.length+' ตัวอักษร':'PDF ไม่มีข้อความที่เลือกได้ อาจเป็นภาพสแกน';}catch(err){state.profile.cvReadStatus='อ่านข้อความจาก PDF ไม่สำเร็จ · ระบบยังจับคู่จากทักษะ/โปรเจกต์ที่กรอกได้';}}else state.profile.cvReadStatus='ตัวอ่าน PDF ไม่พร้อม · ระบบจับคู่จากทักษะ/โปรเจกต์ที่กรอก';go('jobs')}}
function jobs(){let ranked=JOBS.map((j,i)=>({...j,i,match:matchJob(j)})).sort((a,b)=>b.match-a.match);state.jobResults=ranked;state.jobLimit=30;app.innerHTML=`<div class="stephead"><span class="stepno">02 / 05</span><h2>พี่ WIL คัดงานมาให้แล้ว</h2><small>584 REFERENCE ROLES · 2564—2568</small></div><div class="resulthead"><div><div class="eyebrow">MATCHED FOR ${esc(state.profile.name||'YOU')}</div><h2>งานที่น่าจะใช่</h2></div><input id="search" class="search" placeholder="ค้นหาตำแหน่ง / บริษัท..."></div><p class="muted">จับคู่จาก CV PDF, ทักษะและสาขา · ${esc(state.profile.cvReadStatus||'พร้อมจับคู่จาก CV')} · รายการอ้างอิงจากปี 2564–2568 ไม่ใช่ตำแหน่งที่กำลังเปิดรับ · บริษัทและพนักงานในเรื่องเป็นข้อมูล/ตัวละครประกอบ ไม่ได้ติดต่อจริง</p><div id="jobCount" class="small"></div><div class="jobgrid" id="jobgrid"></div><div class="rowactions"><span class="small">ทุกการสัมภาษณ์และผลคัดเลือกเป็น AI จำลอง</span><button class="secondary" onclick="go('profile')">← แก้โปรไฟล์</button></div>`;let draw=()=>{let q=$('#search').value.toLowerCase(),all=state.jobResults.filter(j=>(j.role+' '+j.company+' '+j.description+' '+j.spec).toLowerCase().includes(q));$('#jobgrid').innerHTML=jobCards(all.slice(0,state.jobLimit));$('#jobCount').innerHTML=`แสดง ${Math.min(all.length,state.jobLimit)} จาก ${all.length} ตำแหน่งที่พบ`;let more=document.createElement('button');more.className='secondary';more.textContent='แสดงตำแหน่งเพิ่ม';more.style.margin='18px auto';more.style.display=all.length>state.jobLimit?'block':'none';more.onclick=()=>{state.jobLimit+=30;draw()};$('#jobgrid').after(more)};$('#search').oninput=()=>{state.jobLimit=30;draw()};draw()}
function jobCards(list){return list.length?list.map(j=>`<article class="job"><span class="tag">${esc(j.company)} · ปี ${j.year}</span><h3>${esc(j.role)}</h3><p>${esc(j.description)}</p><details class="jobdetails"><summary>ดูคุณสมบัติและสวัสดิการ</summary><p><b>ทักษะที่ต้องการ:</b> ${esc(j.spec||'ไม่ระบุในข้อมูลต้นทาง')}</p><p><b>สวัสดิการ/ค่าตอบแทน:</b> ${esc(j.benefits||'ไม่ระบุในข้อมูลต้นทาง')}</p></details><div class="jobfoot"><span class="match">${j.match}% MATCH</span><button onclick="chooseJob(${j.i})">เลือกเส้นทางจำลอง →</button></div></article>`).join(''):'<p class="muted">ไม่พบตำแหน่งที่ค้นหา</p>'}
function chooseJob(i){state.selected=JOBS[i];state.jobIndex=i;state.cvMatch=state.jobResults?.find(j=>j.i===i)?.match||matchJob(state.selected);state.interviewAttempts=0;state.trainingRound=1;state.runSeed=(crypto?.getRandomValues?.(new Uint32Array(1))?.[0]||Math.floor(Math.random()*4294967295))>>>0;go('academy')}
function roleSkillKey(){return category(state.selected||{role:''})}function roleReadiness(){return Math.min(100,(state.cvMatch||42)+(state.skills[roleSkillKey()]||0))}function roleChallengePrompt(){return({dev:'บั๊กเกิดเฉพาะเมื่อเรียก API ซ้ำ · แยกสาเหตุและเลือกวิธีทดสอบ',design:'ผู้ใช้หาปุ่มหลักไม่เจอ · จัดลำดับข้อมูลและทดสอบต้นแบบ',marketing:'แคมเปญได้ยอดคลิกแต่ไม่มีคนสมัคร · เลือกตัวชี้วัดและทดลองข้อความใหม่',analyst:'ข้อมูลสองแหล่งให้ตัวเลขต่างกัน · ตรวจที่มาและอธิบายข้อจำกัด',test:'ฟังก์ชันผ่านกรณีปกติแต่ยังไม่ทดสอบข้อมูลผิดรูปแบบ · เลือกกรณีเสี่ยง',support:'ผู้ใช้แจ้งปัญหาไม่ครบและกำลังรอ · ถามเก็บข้อมูลและสื่อสารขั้นตอนถัดไป',general:'งานหลายชิ้นชนกำหนดส่ง · ขอข้อมูลและจัดลำดับผลกระทบ'})[roleSkillKey()]||'รับโจทย์งานจริงจำลองแล้วเลือกวิธีทำอย่างมีเหตุผล'}function skillDifficulty(skill){let score=(state.skills[skill]||0)+Math.floor((state.skills[roleSkillKey()]||0)/2);return Math.min(3,1+Math.floor(score/24))}
