function answerMonth(i){let run=state.monthRun||state.runEvents[state.month]||selectMonthEvents(state.month),e=run[state.monthEventIndex||0],o=e.opts[i];state.score+=o[2];state.monthScore=(state.monthScore||0)+o[2];let skill=e.skill||(e.scene==='interview'?'soft':'hard');state.skills[skill]=(state.skills[skill]||0)+o[2];state.pendingMonthFeedback=`${o[1]} ${e.coachTail||''}`;state.log.push({title:`เดือน ${state.month+1} · เหตุการณ์ ${(state.monthEventIndex||0)+1}/${run.length} · ${e.title}`,text:o[1]});$('#coach').innerHTML=`<b>โค้ช AI:</b> ${esc(o[1])} ${esc(e.coachTail||'')}<br><button class="primary" style="margin-top:10px" onclick="continueMonth()">ทบทวนแล้ว ไปต่อ →</button>`;document.querySelectorAll('.choice').forEach(b=>b.disabled=true)}
